draw((-0.7,0)--(0.7,0));
draw((0,-0.7)--(0,0.7));

dot("$\frac{1}{2} + \frac{i}{2 \sqrt{3}}$", (1/2,1/(2*sqrt(3))), dir(0));
dot("$\frac{1}{2} - \frac{i}{2 \sqrt{3}}$", (1/2,-1/(2*sqrt(3))), dir(0));
